  248 impl CompiledPatterns {
  249     /// `widen`: `Some(windows)` to read each pattern ignoring case — it is
  250     /// widened under that platform's rule before it is compiled
  251     /// ([`crate::case_fold::widen_case`]); `None` to read it as written. A
  252     /// pattern the compiler refuses is kept, and compared, as written
  253     /// either way.
  254     fn compile(patterns: &[String], widen: Option<bool>) -> std::sync::Arc<Self> {
  255         compiled(patterns, widen).unwrap_or_else(|_| {
  256             std::sync::Arc::new(Self {
  257                 globs: globset::GlobSet::empty(),
  258                 refused: patterns.to_vec(),
  259             })
  260         })
  261     }
