  263     /// [`Self::compile`], or the error when the set as a whole cannot be
  264     /// built. cr-ecm1-2: `compile` answers that failure by comparing EVERY
  265     /// pattern as text, which names far less than the globs did — so
  266     /// [`FileFilter::validate_globs`] asks here first and refuses the
  267     /// filter, and no validated filter reaches that fallback.
  268     fn build(
  269         patterns: &[String],
  270         widen: Option<bool>,
  271     ) -> std::result::Result<Self, globset::Error> {
  272         #[cfg(test)]
  273         COMPILATIONS.lock().push((patterns.to_vec(), widen));
  274         let mut builder = globset::GlobSetBuilder::new();
  275         let mut refused = Vec::new();
  276         for pattern in patterns {
  277             match globset::Glob::new(&read_pattern(pattern, widen)) {
  278                 Ok(glob) => {
  279                     builder.add(glob);
  280                 }
  281                 Err(_) => refused.push(pattern.clone()),
  282             }
  283         }
  284         Ok(Self {
  285             globs: builder.build()?,
  286             refused,
  287         })
  288     }
