  294     /// Whether a pattern names `name` — its bytes as [`match_bytes`] gives
  295     /// them. Only a pattern the compiler refused is compared as text.
  296     fn is_match(&self, name: &[u8]) -> bool {
  297         self.globs
  298             .is_match_candidate(&globset::Candidate::from_bytes(name))
  299             || (!self.refused.is_empty() && {
  300                 let text = String::from_utf8_lossy(name);
  301                 self.refused.iter().any(|p| glob_match(p, &text))
