  422 fn compiled(
  423     patterns: &[String],
  424     widen: Option<bool>,
  425 ) -> std::result::Result<std::sync::Arc<CompiledPatterns>, globset::Error> {
  426     if patterns.is_empty() {
  427         return Ok(std::sync::Arc::new(CompiledPatterns::default()));
  428     }
  429     if let Some(held) = COMPILED.lock().get(patterns, widen) {
