  437 /// cr-ecm2-2: the bytes a pattern is matched against for `name` — a file
  438 /// name, or a relative path. On Unix they are the name's OWN bytes, valid
  439 /// UTF-8 or not: `?` and a class match one byte (Q10), so `?.txt` names a
  440 /// file whose name is the single byte `0xFF` and then `.txt`. Matching
  441 /// used to go through `to_string_lossy`, which writes each bad byte as the
  442 /// three bytes of U+FFFD: that file was named by `???.txt` and not by
  443 /// `?.txt`, and a mirror deleted it from under an exclude that named it.
  444 /// On Windows a name is UTF-16 and has no bytes of its own; it is read as
  445 /// text, ill-formed UTF-16 replaced, exactly as the glob engine itself
  446 /// reads a Windows path.
  447 pub(crate) fn match_bytes(name: &std::ffi::OsStr) -> std::borrow::Cow<'_, [u8]> {
  448     #[cfg(unix)]
  449     {
  450         use std::os::unix::ffi::OsStrExt as _;
  451         std::borrow::Cow::Borrowed(name.as_bytes())
  452     }
  453     #[cfg(not(unix))]
  454     {
  455         match name.to_string_lossy() {
  456             std::borrow::Cow::Borrowed(text) => std::borrow::Cow::Borrowed(text.as_bytes()),
  457             std::borrow::Cow::Owned(text) => std::borrow::Cow::Owned(text.into_bytes()),
  458         }
  459     }
  460 }
