  464 fn read_pattern(pattern: &str, widen: Option<bool>) -> std::borrow::Cow<'_, str> {
  465     match widen {
  466         Some(windows) => std::borrow::Cow::Owned(crate::case_fold::widen_case(pattern, windows)),
  467         None => std::borrow::Cow::Borrowed(pattern),
  468     }
