  274         // entry it names is stored under several names), without the
  275         // `./` that anchors it at the source: that is how it is written
  276         // for the matcher, not part of what it names.
  277         let became = resolved
  278             .became
  279             .get(at)
  280             .and_then(|span| resolved.patterns.get(span.start))
  281             .filter(|_| is_absolute_pattern(typed, windows))
  282             .map(|pattern| pattern.strip_prefix("./").unwrap_or(pattern));
  283         noted.push(Noted {
  284             typed,
  285             read_as: became.unwrap_or(typed),
  286             file,
  287             role: Role::Exclude,
