  313 /// Everything about a filter that can be refused from the command's own
  314 /// words, checked without building it: the patterns, exactly as [`build`]
  491 /// — `--ignore-case`, or `--match-case`, which changes no matching and
  492 /// says the operator knows (Q9) — none with `-y`, and none when no pattern
  493 /// holds a letter. `mirror` shows it in its question; a run that asks
  494 /// nothing prints it as a note.
  495 ///
  496 /// cr-ecm4-3: `resolved` is what this run's excludes resolved to; the line
  497 /// is derived from it, so an exclude just reported as unable to match
  498 /// anything is not then described as matching.
  499 fn case_note(args: &TransferArgs, resolved: &filter::ResolvedExcludes) -> Option<String> {
  500     if args.ignore_case || args.match_case || args.yes {
  501         return None;
  502     }
  503     // cr-ecm3-5: a list of names overrides every pattern (`--files-from`,
  504     // and the list of files a retry sends again): the patterns then name
  505     // nothing in this run, and a line about them would mislead.
  506     if args.files_from.is_some() || args.retry_only.is_some() || args.retry_only_raw.is_some() {
  507         return None;
  508     }
  509     // Slice 3b: each pattern with the pattern file it was read from.
  510     let origin = |origins: &[Option<PathBuf>], at: usize| {
  511         origins
  512             .get(at)
  513             .and_then(Option::as_ref)
  514             .map(|file| file.display().to_string())
  515     };
  516     let with_origins = |patterns: &[String], origins: &[Option<PathBuf>]| -> Vec<Option<String>> {
  517         (0..patterns.len()).map(|at| origin(origins, at)).collect()
  518     };
  519     let exclude_files = with_origins(&args.exclude, &args.exclude_origin);
  520     let include_files = with_origins(&args.include, &args.include_origin);
  521     fn paired<'a>(
  522         patterns: &'a [String],
  523         files: &'a [Option<String>],
  524     ) -> Vec<(&'a str, Option<&'a str>)> {
  525         patterns
  526             .iter()
  527             .map(String::as_str)
  528             .zip(files.iter().map(Option::as_deref))
  529             .collect()
  530     }
  531     filter::case_note(
  532         &paired(&args.exclude, &exclude_files),
  533         &paired(&args.include, &include_files),
  534         resolved,
  535     )
